@sgl.function
def extract_info(s, text):
    s += "Text: " + text + "\n"
    s += "Name: " + sgl.gen("name", regex=r"[A-Z][a-z]+") + "\n"
    s += "Age: " + sgl.gen("age", regex=r"\d+") + "\n"
    s += "Email: " + sgl.gen("email", regex=r"[^@]+@[^@]+")

